IF DB_ID(N'jncity') IS NULL CREATE DATABASE jncity;
GO
USE jncity;
GO

-- ============ 表 dbo.users（2 条）============
IF OBJECT_ID(N'dbo.users', N'U') IS NOT NULL DROP TABLE dbo.users;
GO
CREATE TABLE dbo.users (
  id            INT IDENTITY(1,1) PRIMARY KEY,
  username      NVARCHAR(50)  NOT NULL UNIQUE,
  password_hash NVARCHAR(100) NOT NULL,
  created_at    DATETIME      DEFAULT GETDATE()
)
GO

SET IDENTITY_INSERT dbo.users ON;
GO
SET IDENTITY_INSERT dbo.users OFF;
GO

-- ============ 表 dbo.stations（1425 条）============
IF OBJECT_ID(N'dbo.stations', N'U') IS NOT NULL DROP TABLE dbo.stations;
GO
CREATE TABLE dbo.stations (
  id       INT IDENTITY(1,1) PRIMARY KEY,
  objectid INT,
  name     NVARCHAR(100),
  lng      FLOAT,
  lat      FLOAT,
  area     NVARCHAR(50),
  type     NVARCHAR(20)
)
GO

SET IDENTITY_INSERT dbo.stations ON;
GO
SET IDENTITY_INSERT dbo.stations OFF;
GO
